sys_script_include.script:
function PromptCodeReview(strSourceCode)
{
	if (IsActive() == false)
	{
		return false;
	}

	var GetStringValue = x_snc_devtools.GetStringValue;
	var RenderValue = x_snc_devtools.RenderValue;

	strSourceCode = GetStringValue(strSourceCode);

	if (strSourceCode == '')
	{
		return false;
	}

	var strPrompt = '';
	strPrompt += 'Find defects, optimize, document and complete the provided source code.\n';
	strPrompt += 'Undefined functions are NO defects. Please ignore them!\n';
	strPrompt += 'Use ECMAScript 2009!\n';
	strPrompt += 'The code runs on a ServiceNow server!\n';
	strPrompt += 'Do not use single-character variable names!\n';
	strPrompt += 'Source Code:\n';
	strPrompt += strSourceCode+'\n';

	var strAnswer = Prompt(strPrompt);

	if (strAnswer == '')
	{
		return false;
	}
	return strAnswer;
}
